/* ── WEB AUDIO SYNTHESIZER (Guaranteed to work, no base64 blocks) ── */
const AudioContext = window.AudioContext || window.webkitAudioContext;
let audioCtx;
let audioInit = false;

function initAudio() {
    if(!audioInit) {
        try {
            audioCtx = new AudioContext();
            audioInit = true;
        } catch(e) {
            audioInit = true; // mark as attempted so we don't retry on every call
            audioCtx = null;
        }
    }
    if (audioCtx && audioCtx.state === 'suspended') {
        try { audioCtx.resume(); } catch(e) {}
    }
}

