function playTick() {
    initAudio();
    if(!audioCtx) return;
    const sound = clickSounds[currentClickSound] || clickSounds['neon'];
    try { sound.play(audioCtx); } catch(e) {}
}

function setClickSound(name) {
    currentClickSound = name;
    localStorage.setItem('mosClickSound', name);
    // Update UI active state
    document.querySelectorAll('.sound-card').forEach(c => c.classList.remove('active-sound'));
    const active = document.querySelector(`.sound-card[data-sound="${name}"]`);
    if (active) active.classList.add('active-sound');
    // Play preview
    playTick();
    if (typeof showToast === 'function') {
        const s = clickSounds[name];
        showToast((s ? s.icon + ' ' + s.label : name) + ' selected', '🔊');
    }
}

// Bind audio init to first touch to bypass browser policies
document.addEventListener('click', initAudio, {once:true});
document.addEventListener('touchstart', initAudio, {once:true});

/* ── EXECUTION ENGINE — Ax Manager only, 100% rootless ADB ── */
let logs = [];
let currentModuleCategory = 'PERFORMANCE';
function executeShellRaw(cmd) {
    let env = "{}";
    if (typeof Axeron !== 'undefined' && Axeron.exec) { try { return Axeron.exec(cmd, env); } catch(e) { return Axeron.exec(cmd); } }
    if (typeof axeron !== 'undefined' && axeron.exec) { try { return axeron.exec(cmd, env); } catch(e) { return axeron.exec(cmd); } }
    if (typeof Android !== 'undefined') { if (Android.execShell) return Android.execShell(cmd); if (Android.exec) return Android.exec(cmd); }
    if (typeof window.exec === 'function') return window.exec(cmd);
    throw new Error("No Ax Manager bridge");
}

let _suppressRenderLogs = false;
let _execQ = [];
let _execRunning = false;
function _mosRunExecQ() {
    _execRunning = true;
    const pending = [];
    let sinceRender = 0;
    function step() {
        const start = performance.now();
        while (_execQ.length && (performance.now() - start) < 30) {
            const cmd = _execQ.shift();
            let time = new Date().toTimeString().split(' ')[0];
            try {
                executeShellRaw(cmd);
                pending.push({ time: time, type: 'INFO', msg: cmd });
            } catch (e) {
                pending.push({ time: time, type: 'ERR', msg: cmd + " (" + (e.message || '') + ")" });
            }
            sinceRender++;
        }
        if (pending.length) {
            logs.push.apply(logs, pending);
            pending.length = 0;
        }
        if (_execQ.length) {
            if (!_suppressRenderLogs && sinceRender >= 12) { renderLogs(); sinceRender = 0; }
            setTimeout(step, 10);
        } else {
            if (!_suppressRenderLogs) renderLogs();
            _execRunning = false;
        }
    }
    setTimeout(step, 0);
}
function execQueue(cmds) {
    playTick();
    if (!Array.isArray(cmds)) cmds = [cmds];
    cmds.forEach(function (cmd) {
        if (cmd && String(cmd).trim()) _execQ.push(String(cmd).trim());
    });
    if (!_execRunning) _mosRunExecQ();
}
if (typeof window !== 'undefined') window.__execQueued = function () { return _execQ.length; };

function runCustomCmd() {
    let input = document.getElementById('customCmd');
    if(input.value.trim() !== "") {
        execQueue([input.value]);
        const strings = getLang();
        showToast(strings.toast_cmd, "💻");
        input.value = "";
    }
}

function showToast(msg, icon="💎") {
    const t = document.getElementById('toast');
    if (!t) return;
    let iconHtml;
    if (icon && /^[a-z0-9-]+$/i.test(icon)) {
        iconHtml = '<ion-icon name="' + icon + '" class="toast-ico"></ion-icon>';
    } else {
        iconHtml = '<span class="toast-ico">' + (icon || '') + '</span>';
    }
    t.innerHTML = iconHtml + ' <span>' + msg + '</span>';
    if (window.deEmoji) window.deEmoji(t);
    t.classList.add('show');
    clearTimeout(t._hideTimer);
    t._hideTimer = setTimeout(() => t.classList.remove('show'), 3000);
}

function switchTab(tabId, element) {
    playTick();
    document.querySelectorAll('.page').forEach(page => {
        page.classList.remove('active');
        page.setAttribute('aria-hidden', 'true');
        page.style.display = 'none';
        page.style.zIndex = '0';
        page.style.visibility = 'hidden';
        page.style.opacity = '0';
        page.style.pointerEvents = 'none';
    });
    const tab = document.getElementById(tabId);
    if (!tab) return;
    tab.style.display = 'block';
    tab.style.zIndex = '50';
    tab.style.visibility = 'visible';
    tab.style.opacity = '1';
    tab.style.pointerEvents = 'auto';
    tab.classList.add('active');
    tab.removeAttribute('aria-hidden');
    // Premium entrance: fade + lift, restarted even on rapid switches
    tab.classList.remove('tab-enter');
    void tab.offsetWidth;
    tab.classList.add('tab-enter');
    tab.scrollTop = 0;
    document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
    if (element) {
        element.classList.add('active');
        const nav = element.closest('.bottom-nav');
        if (nav) {
            const navRect = nav.getBoundingClientRect();
            const elRect  = element.getBoundingClientRect();
            nav.scrollTo({ left: nav.scrollLeft + (elRect.left - navRect.left) - (navRect.width / 2) + (elRect.width / 2), behavior: 'smooth' });
        }
    }
}

function renderLogs() {
    const box = document.getElementById('terminal-logs');
    if (!box) return;
    const slice = logs.slice(-80);
    const parts = new Array(slice.length);
    for (let i = 0; i < slice.length; i++) {
        const l = slice[i];
        const col = l.type === 'ERR' ? 'log-err' : (l.type === 'SKIP' ? 'log-skip' : 'log-info');
        parts[i] = `<div class="log-line"><span class="log-time">[${l.time}]</span><span class="${col}">[${l.type}]</span><span class="log-cmd">${l.msg}</span></div>`;
    }
    box.innerHTML = parts.join('');
    box.scrollTop = box.scrollHeight;
}

function clearLogs() {
    logs = [];
    renderLogs();
    showToast((getLang()).toast_terminal_cleared, '🗑️');
    playTick();
}

function exportLogs() {
    if (logs.length === 0) { showToast((getLang()).toast_no_logs, '⚠️'); return; }
    let text = logs.map(l => `[${l.time}] [${l.type}] ${l.msg}`).join('\n');
    let blob = new Blob([text], { type: 'text/plain' });
    let url = URL.createObjectURL(blob);
    let a = document.createElement('a');
    a.href = url;
    a.download = 'mos_terminal_' + new Date().toISOString().slice(0,19).replace(/:/g,'-') + '.log';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast((getLang()).toast_log_exported, '📄');
    playTick();
}

// Cached metric DOM refs (populated on first call)
const _m = {};
function updateMetrics() {
    if (!_m.cv) {
        _m.cv  = document.getElementById('cpu-val');
        _m.cb  = document.querySelectorAll('#cpu-chart .bar');
        _m.rv  = document.getElementById('ram-val');
        _m.rb  = document.querySelectorAll('#ram-chart .bar');
    }
    if (_m.cv) _m.cv.innerText = (Math.floor(Math.random() * 20 + 10)) + '%';
    _m.cb.forEach(b => { b.style.height = (Math.floor(Math.random() * 80 + 20)) + '%'; });
    if (_m.rv) _m.rv.innerText = (Math.floor(Math.random() * 25 + 40)) + '%';
    _m.rb.forEach(b => { b.style.height = (Math.floor(Math.random() * 60 + 40)) + '%'; });
}

/* ── 3D HYPERGLASS PHYSICS ENGINE ── */
function init3DPhysics() {
    const isRTL = document.documentElement.getAttribute('dir') === 'rtl';
    document.querySelectorAll('.glass, .glass-sm').forEach(card => {
        if (card.dataset.physicsInit) return;
        card.dataset.physicsInit = '1';
        let _raf = null;
        card.addEventListener('mousemove', e => {
            if (_raf) return; // RAF throttle — max 1 update per frame
            _raf = requestAnimationFrame(() => {
                _raf = null;
                const rect = card.getBoundingClientRect();
                const x = e.clientX - rect.left;
                const y = e.clientY - rect.top;
                const rotateX = ((y / rect.height) - 0.5) * -14;
                const rotateY = ((x / rect.width)  - 0.5) * (isRTL ? -14 : 14);
                card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale3d(1.02,1.02,1.02)`;
                card.style.borderColor = 'var(--acc)';
            });
        }, { passive: true });
        card.addEventListener('mouseleave', () => {
            cancelAnimationFrame(_raf); _raf = null;
            card.style.transform = 'perspective(1000px) rotateX(0) rotateY(0) scale3d(1,1,1)';
            card.style.borderColor = 'var(--glass-border)';
        });
    });
}

function initParticles() {
    const canvas = document.getElementById('particles');
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    const W = window.innerWidth, H = window.innerHeight;
    canvas.width = W; canvas.height = H;
    // Reduce particle count on low-end devices (< 4GB RAM heuristic via screen area)
    const COUNT = (W * H > 800000) ? 35 : 25;
    const parts = [];
    for (let i = 0; i < COUNT; i++) {
        parts.push({ x: Math.random() * W, y: Math.random() * H, s: Math.random() * 1.8 + 0.8, d: Math.random() * 0.45 + 0.15 });
    }
    let rafId = null;
    function draw() {
        ctx.clearRect(0, 0, W, H);
        ctx.fillStyle = 'rgba(0,242,254,0.45)';
        for (let i = 0; i < COUNT; i++) {
            const p = parts[i];
            ctx.beginPath(); ctx.arc(p.x, p.y, p.s, 0, Math.PI * 2); ctx.fill();
            p.y -= p.d;
            if (p.y < 0) p.y = H;
        }
        rafId = requestAnimationFrame(draw);
    }
    // Pause when tab is hidden to save GPU/CPU
    document.addEventListener('visibilitychange', () => {
        if (document.hidden) { cancelAnimationFrame(rafId); rafId = null; }
        else if (!rafId) rafId = requestAnimationFrame(draw);
    });
    rafId = requestAnimationFrame(draw);
}

