// ──────────────────────────────────────────────────────────────────────────────
// MODULE DATABASE ENGINE
// ──────────────────────────────────────────────────────────────────────────────
function categorizeModule(module) {
    if (module.category) return module.category;
    const text = `${module.name} ${module.desc} ${module.cmd}`.toLowerCase();
    if (text.includes('battery') || text.includes('doze') || text.includes('idle') || text.includes('nfc off') || text.includes('bluetooth off') || text.includes('hibernate')) return 'BATTERY';
    if (text.includes('game') || text.includes('fps') || text.includes('touch') || text.includes('latency') || text.includes('adreno') || text.includes('latch') || text.includes('ping') || text.includes('dnd') || text.includes('lmkd') || text.includes('tcp')) return 'GAMING';
    if (text.includes('render') || text.includes('vulkan') || text.includes('skia') || text.includes('hwui') || text.includes('surfaceflinger') || text.includes('egl') || text.includes('compositor') || text.includes('frame buffer')) return 'RENDERER';
    if (text.includes('reset') || text.includes('restore') || text.includes('dark') || text.includes('font') || text.includes('rotation') || text.includes('balanced')) return 'BALANCED';
    if (text.includes('performance') || text.includes('boost') || text.includes('cpu') || text.includes('ram') || text.includes('scheduler') || text.includes('art') || text.includes('dalvik') || text.includes('i/o') || text.includes('zram') || text.includes('usap') || text.includes('sched')) return 'PERFORMANCE';
    return 'BALANCED';
}

const runtimeModuleRegistry = (() => {
    const registry = [];
    const seen = new Set();

    premiumNewModules.forEach((m, i) => {
        const key = `${m.name}_${m.cmd}_${m.category}`;
        if (seen.has(key)) return;
        seen.add(key);

        registry.push({
            id: `mod_${i}_${Math.random().toString(36).slice(2,8)}`,
            ...m
        });
    });

    console.log('[MOS] Runtime registry loaded:', registry.length);
    return registry;
})();

let generatedDatabase = runtimeModuleRegistry;

function filterModuleCategory(category, element) {
    playTick();
    currentModuleCategory = category;
    document.querySelectorAll('.module-preset-btn').forEach(btn => btn.classList.remove('active'));
    if (element) element.classList.add('active');
    const injectBtn = document.getElementById('injectBtn');
    if (injectBtn) {
        injectBtn.innerText = mosF('inject_preset_btn',{s:category});
    }
    renderPremiumDatabase(1, document.getElementById('searchBar')?.value || '');
}

let currentPage = 1;
const ITEMS_PER_PAGE = 50;

function renderPremiumDatabase(page, query = "") {
    const container = document.getElementById('titanDB');
    if (!container) return;

    let filtered = generatedDatabase;
    if (currentModuleCategory !== 'ALL') {
        filtered = filtered.filter(m => categorizeModule(m) === currentModuleCategory);
    }
    if (query.trim() !== "") {
        const q = query.toLowerCase();
        filtered = filtered.filter(m =>
            m.name.toLowerCase().includes(q) ||
            m.desc.toLowerCase().includes(q) ||
            m.cmd.toLowerCase().includes(q)
        );
    }

    const total = filtered.length;
    const totalPages = Math.ceil(total / ITEMS_PER_PAGE) || 1;
    page = Math.max(1, Math.min(page, totalPages));
    currentPage = page;

    const start = (page - 1) * ITEMS_PER_PAGE;
    const slice = filtered.slice(start, start + ITEMS_PER_PAGE);

    // Categories share the active theme accent so nothing breaks the palette.
    const catColors = {
        GAMING:'var(--acc)', RENDERER:'var(--acc)', PERFORMANCE:'var(--acc)',
        BATTERY:'var(--acc)', BALANCED:'var(--acc)'
    };
    const catBg = 'rgba(var(--acc-rgb),0.12)';

    let html = `<div style="text-align:center;color:var(--text-dim);font-family:'JetBrains Mono',monospace;font-size:11px;margin-bottom:14px;letter-spacing:1px;">
        mosF('mod_count_tpl',{a:start+1,b:Math.min(start+ITEMS_PER_PAGE,total),c:'<span style="color:var(--acc);font-weight:700">'+total+'</span>'})
    </div>`;

    for (let i = 0; i < slice.length; i++) {
        const t = slice[i];
        const cat = categorizeModule(t);
        const cc = catColors[cat] || 'var(--acc)';
        const safeCmd = t.cmd.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
        const safeName = t.name.replace(/'/g,"\\'");
        html += `<div class="tweak-item glass-sm" style="margin-bottom:10px;border-left:2px solid ${cc}33;" onclick="execQueue(('${safeCmd}'.indexOf('&&')>=0?'${safeCmd}'.split('&&').map(s=>s.trim()):[('${safeCmd}').trim()]));showToast('💉 ${safeName} injected','💉')">
<div class="tweak-info">
<div style="display:flex;align-items:center;gap:7px;margin-bottom:3px;">
<span style="font-family:'JetBrains Mono',monospace;font-size:8px;font-weight:700;padding:2px 5px;border-radius:4px;background:${catBg};color:${cc};letter-spacing:0.8px;flex-shrink:0">${cat}</span>
<div class="title-sm" style="font-size:12px;font-weight:700;">${t.name}</div>
</div>
<div class="text-xs" style="color:var(--text-dim);margin-bottom:3px;">${t.desc}</div>
<div style="font-family:'JetBrains Mono',monospace;font-size:9px;color:var(--acc);opacity:0.65;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${t.cmd}</div>
</div>
<button class="btn-run" style="flex-shrink:0;font-size:10px;padding:8px 10px;letter-spacing:0.5px;">INJECT</button>
</div>`;
    }

    html += `<div style="display:flex;justify-content:space-between;align-items:center;margin-top:20px;gap:8px;">
<button class="btn-run" style="flex:1;padding:13px;font-size:13px;" onclick="renderPremiumDatabase(${page-1},document.getElementById('searchBar')?.value||'')" ${page===1?'disabled style="opacity:0.35;pointer-events:none"':''}>← PREV</button>
<span style="font-family:'JetBrains Mono',monospace;font-size:10px;color:var(--text-dim);white-space:nowrap">${page} / ${totalPages}</span>
<button class="btn-run" style="flex:1;padding:13px;font-size:13px;" onclick="renderPremiumDatabase(${page+1},document.getElementById('searchBar')?.value||'')" ${page===totalPages?'disabled style="opacity:0.35;pointer-events:none"':''}>NEXT →</button>
</div>`;

    container.innerHTML = html;
    // Re-init physics only for newly injected items inside the container,
    // NOT for the entire page — avoids listener pile-up on preset cards
    // and stops the glitch when switching BATTERY / PERFORMANCE categories.
    container.querySelectorAll('.glass, .glass-sm').forEach(card => {
        if (card.dataset.physicsInit) return;
        card.dataset.physicsInit = '1';
        const isRTL = document.documentElement.getAttribute('dir') === 'rtl';
        let _raf = null;
        card.addEventListener('mousemove', e => {
            if (_raf) return;
            _raf = requestAnimationFrame(() => {
                _raf = null;
                const rect = card.getBoundingClientRect();
                const x = e.clientX - rect.left;
                const y = e.clientY - rect.top;
                const rotateX = ((y / rect.height) - 0.5) * -14;
                const rotateY = ((x / rect.width)  - 0.5) * (isRTL ? -14 : 14);
                card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale3d(1.02,1.02,1.02)`;
                card.style.borderColor = 'var(--acc)';
            });
        }, { passive: true });
        card.addEventListener('mouseleave', () => {
            cancelAnimationFrame(_raf); _raf = null;
            card.style.transform = 'perspective(1000px) rotateX(0) rotateY(0) scale3d(1,1,1)';
            card.style.borderColor = 'var(--glass-border)';
        });
    });
}

let _searchTimer = null;
function handleSearch(query) {
    clearTimeout(_searchTimer);
    _searchTimer = setTimeout(() => { currentPage = 1; renderPremiumDatabase(1, query); }, 180);
}

function injectAllSafe() {
    playTick();
    if (window.__mosInjectBusy) { showToast('Already injecting...', '⏳'); return; }
    window.__mosInjectBusy = true;
    const injectBtn = document.getElementById('injectBtn');
    if (injectBtn) injectBtn.innerText = (getLang()).toast_injecting;
    // Hide any previous completion note
    const prevNote = document.getElementById('inject-complete-note');
    if (prevNote) { prevNote.style.display = 'none'; prevNote.style.opacity = '0'; }

    setTimeout(() => {

        // ── Filter modules by selected category ──
        let mods = generatedDatabase;
        if (currentModuleCategory !== 'ALL') {
            mods = mods.filter(m => categorizeModule(m) === currentModuleCategory);
        }

        // ── Skip disruptive UI-appearance & connectivity overrides ──
        // These commands change screen resolution/DPI/font scale, force
        // light/dark theme & color modes (causing the "turned white" look),
        // or rewrite DNS/captive-portal connectivity settings (causing
        // WiFi to lose internet access). They conflict across presets and
        // are not actual gaming performance tweaks, so they are excluded
        // from "Inject All" — only stable gaming tweaks remain.
        const SKIP_CMD_PATTERN = /font_scale|wm\s+(size|density)|display_density_forced|display_size|ui_night_mode|uimode\s+night|night_display|display_color_mode|display_inversion_enabled|high_text_contrast_enabled|hdr_output_control|hdr_display_enabled|enable_hdr|captive_portal|private_dns|net\.dns[12]|wallpaper/i;

        // ── Collect commands — skipping disruptive theme/display/DNS overrides ──
        const finalCmds = [];
        mods.forEach(m => {
            const rawCmd = (m.cmd || '').trim();
            if (!rawCmd) return;
            rawCmd.split(/&&|;/).map(s => s.trim()).filter(Boolean).forEach(cmd => {
                if (SKIP_CMD_PATTERN.test(cmd)) return;
                if (window.mosIsDangerousCmd && window.mosIsDangerousCmd(cmd)) return;
                finalCmds.push(cmd);
            });
        });

        const total = finalCmds.length;
        const BATCH = 20;
        let idx = 0;

        _suppressRenderLogs = true;
        function nextBatch() {
            if (idx >= total) {
                _suppressRenderLogs = false;
                renderLogs();
                const preset = currentModuleCategory;
                showToast(mosF('inject_toast',{n:total,c:preset}), '🛡️');
                if (injectBtn) injectBtn.innerText = mosF('inject_preset_btn',{s:currentModuleCategory});
                const noteEl = document.getElementById('inject-complete-note');
                const countEl = document.getElementById('inject-complete-count');
                if (noteEl) {
                    noteEl.style.opacity = '0';
                    noteEl.style.display = 'block';
                    requestAnimationFrame(() => {
                        noteEl.style.transition = 'opacity 0.4s ease';
                        noteEl.style.opacity = '1';
                    });
                }
                if (countEl) countEl.textContent = mosF('mods_applied',{n:total,c:preset});
                applyLanguage(currentLang);
                window.__mosInjectBusy = false;
                return;
            }
            execQueue(finalCmds.slice(idx, idx + BATCH));
            idx += BATCH;
            setTimeout(nextBatch, 200);
        }
        nextBatch();

    }, 300);
}

// VIP PRESETS PERSISTENCE
// VIP PRESETS PERSISTENCE
const MOS_PRESET_STORAGE_KEY = 'mos.vip.selectedPreset';

function saveSelectedPreset(presetName) {
    try {
        localStorage.setItem(MOS_PRESET_STORAGE_KEY, presetName);
    } catch (e) {
        console.error('Failed to persist preset:', e);
    }
}

function getSavedPreset() {
    try {
        return localStorage.getItem(MOS_PRESET_STORAGE_KEY) || 'BALANCED';
    } catch (e) {
        console.error('Failed to read saved preset:', e);
        return 'BALANCED';
    }
}

function restoreSavedPreset() {
    const savedPreset = getSavedPreset();
    const presetCard = document.querySelector(`.preset-card[onclick*="'${savedPreset}'"]`) ||
                       document.querySelector(`.preset-card[onclick*='${savedPreset}']`);

    if (!presetCard) {
        console.warn('Saved preset card not found, falling back to BALANCED');
        // Mark BALANCED as active visually
        const balancedCard = document.querySelector('[onclick*="\'BALANCED\'"]');
        if (balancedCard) balancedCard.classList.add('active');
        return;
    }

    // Only restore visual/active state — do NOT re-execute commands on page load.
    // Commands are already applied from the previous session; re-running them
    // without user interaction can crash the AudioContext on strict WebViews
    // (KSU / MMRL) and leave the entire page unresponsive.
    requestAnimationFrame(() => {
        try {
            document.querySelectorAll('.preset-card').forEach(c => c.classList.remove('active'));
            presetCard.classList.add('active');
        } catch (e) {
            console.error('Failed to restore saved preset visual state:', e);
        }
    });
}

// ── HEAVY GAMES UNIVERSAL BOOST ───────────────────────────────────
// Applied on top of every gaming preset: forces best-effort priority,
// speed-profile AOT recompilation, doze/standby whitelisting and
// Game Driver opt-in for the most demanding titles on Android.
// 100% command-based (no root-only ops), safe on all Android 12-15 devices.
const HEAVY_GAMES_PKGS = [
    "com.miHoYo.GenshinImpact",          // Genshin Impact
    "com.miHoYo.Yuanmeng",                // Honkai: Star Rail (global)
    "com.miHoYo.bh3.global",              // Honkai Impact 3rd
    "com.kurogame.wutheringwaves.global", // Wuthering Waves
    "com.blizzard.diabloimmortal",        // Diablo Immortal
    "com.tencent.ig",                     // PUBG Mobile
    "com.activision.callofduty.shooter",  // Call of Duty: Mobile
    "com.garena.game.codm",               // Call of Duty: Mobile (Garena)
    "com.dts.freefireth",                 // Free Fire
    "com.mobile.legends",                 // Mobile Legends: Bang Bang
    "com.ea.gp.apexlegendsmobilefps",     // Apex Legends Mobile
    "com.epicgames.fortnite",             // Fortnite
    "com.roblox.client",                  // Roblox
    "com.mojang.minecraftpe",             // Minecraft
    "com.gameloft.android.ANMP.GloftA9HM",// Asphalt 9: Legends
    "com.ea.games.r3_row",                // Real Racing 3
    "com.supercell.clashofclans",         // Clash of Clans
    "com.netease.lztgglobal",             // LifeAfter
    "com.ngame.allstar.eu",               // Brawl Stars
    "com.nexon.bluearchive"               // Blue Archive
];

function buildHeavyGamesCmds() {
    let out = [
        "// ── Heavy Games: Universal Boost (per-package) ──────"
    ];
    HEAVY_GAMES_PKGS.forEach(pkg => {
        out.push(`cmd game mode performance ${pkg} 2>/dev/null`);
        out.push(`pm compile -m speed-profile -f ${pkg} 2>/dev/null`);
        out.push(`cmd activity set-standby-bucket ${pkg} active 2>/dev/null`);
        out.push(`dumpsys deviceidle whitelist +${pkg} 2>/dev/null`);
        out.push(`appops set ${pkg} RUN_IN_BACKGROUND allow 2>/dev/null`);
        out.push(`appops set ${pkg} RUN_ANY_IN_BACKGROUND allow 2>/dev/null`);
        out.push(`settings put global game_driver_opt_in_apps ${pkg} 2>/dev/null`);
        out.push(`device_config put game_overlay ${pkg}_game_default_frame_rate 120 2>/dev/null`);
    });
    out.push("cmd activity compact system 2>/dev/null");
    return out;
}
const HEAVY_GAMES_CMDS = buildHeavyGamesCmds();

