let currentLang = localStorage.getItem('mos_lang') || 'en';

function getLang() {
    return Object.assign({}, i18nStrings.en, (i18nStrings[currentLang] || {}));
}
function mosT(k) {
    var s = (i18nStrings && (i18nStrings[currentLang] || i18nStrings.en)) || {};
    var v = s[k];
    return (v !== undefined && v !== null) ? v : (i18nStrings.en ? i18nStrings.en[k] : k);
}
function mosF(tpl, map) {
    var s = mosT(tpl);
    for (var k in map) s = s.split('{'+k+'}').join(map[k]);
    return s;
}

function applyLanguage(lang) {
    const strings = Object.assign({}, i18nStrings.en, (i18nStrings[lang] || {}));
    // Translate text content
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (strings[key]) el.innerHTML = strings[key];
    });
    // Translate placeholders
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (strings[key] !== undefined) el.placeholder = strings[key];
    });
    // Swap any emoji in freshly-applied translations for handmade icons
    if (window.deEmoji) window.deEmoji(document.body);
    // Update lang check icons
    ['en','pt','es','fr','hi','ar','zh'].forEach(l => {
        const icon = document.getElementById('lang-check-' + l);
        const card = document.getElementById('lang-' + l);
        if (icon) icon.style.display = (l === lang) ? 'block' : 'none';
        if (card) {
            if (l === lang) card.classList.add('active');
            else card.classList.remove('active');
        }
    });

    // RTL support for Arabic
    const isRTL = (lang === 'ar');
    document.documentElement.setAttribute('dir', isRTL ? 'rtl' : 'ltr');
    document.body.style.textAlign = isRTL ? 'right' : '';

    // Font support for Devanagari (Hindi) and Arabic
    let fontLink = document.getElementById('dynamic-lang-font');
    if (!fontLink) {
        fontLink = document.createElement('link');
        fontLink.id = 'dynamic-lang-font';
        fontLink.rel = 'stylesheet';
        document.head.appendChild(fontLink);
    }
    if (lang === 'hi') {
        fontLink.href = 'https://fonts.googleapis.com/css2?family=Noto+Sans+Devanagari:wght@400;600;700&display=swap';
        document.body.style.fontFamily = "'Noto Sans Devanagari', sans-serif";
    } else if (lang === 'ar') {
        fontLink.href = 'https://fonts.googleapis.com/css2?family=Noto+Sans+Arabic:wght@400;600;700&display=swap';
        document.body.style.fontFamily = "'Noto Sans Arabic', sans-serif";
    } else if (lang === 'zh') {
        fontLink.href = 'https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@400;600;700&display=swap';
        document.body.style.fontFamily = "'Noto Sans SC', sans-serif";
    } else {
        fontLink.href = '';
        document.body.style.fontFamily = '';
    }
}

function setLanguage(lang) {
    currentLang = lang;
    try { localStorage.setItem('mos_lang', lang); } catch(e) {}
    applyLanguage(lang);
    const msg = (i18nStrings[lang] || i18nStrings['en']).toast_lang;
    showToast(msg, '🌐');
    playTick();
}

// INIT
window.onload = () => {
    initParticles();
    renderPremiumDatabase(1);

    // Sparkle canvas effect on splash
    (function initSwordSparks() {
        const canvas = document.getElementById('sparkCanvas');
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        canvas.width = 220; canvas.height = 220;
        const cx = 110, cy = 110;
        const sparks = [];
        const COLORS = ['#ff6a1a','#ff2d2d','#ffffff','#ffb347','#e01e2b'];
        function getAccColor() {
            return getComputedStyle(document.documentElement).getPropertyValue('--acc').trim() || '#e01e2b';
        }
        function spawnSpark() {
            const acc = getAccColor();
            const angle = Math.random() * Math.PI * 2;
            const r = 26 + Math.random() * 30;
            sparks.push({
                x: cx + Math.cos(angle) * r,
                y: cy + Math.sin(angle) * r,
                vx: (Math.random() - 0.5) * 1.4,
                vy: -(0.5 + Math.random() * 1.6),
                life: 1,
                decay: 0.018 + Math.random() * 0.024,
                size: 1.1 + Math.random() * 2.1,
                color: Math.random() > 0.45 ? acc : COLORS[Math.floor(Math.random() * COLORS.length)]
            });
        }
        let splashGone = false;
        function loop() {
            if (splashGone) return;
            ctx.clearRect(0, 0, 220, 220);
            if (Math.random() < 0.45) spawnSpark();
            for (let i = sparks.length - 1; i >= 0; i--) {
                const s = sparks[i];
                s.x += s.vx; s.y += s.vy; s.life -= s.decay;
                if (s.life <= 0) { sparks.splice(i, 1); continue; }
                ctx.save();
                ctx.globalAlpha = s.life * 0.85;
                ctx.fillStyle = s.color;
                ctx.shadowColor = s.color;
                ctx.shadowBlur = 8;
                ctx.beginPath();
                ctx.arc(s.x, s.y, s.size * s.life, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            }
            requestAnimationFrame(loop);
        }
        loop();
        const observer = new MutationObserver(() => {
            const splash = document.getElementById('splash');
            if (splash && splash.style.display === 'none') { splashGone = true; observer.disconnect(); }
        });
        observer.observe(document.getElementById('splash'), { attributes: true, attributeFilter: ['style'] });
    })();

    // HUD clock
    (function initSplashClock() {
        const el = document.getElementById('sp-clock');
        if (!el) return;
        function tick() {
            const n = new Date();
            el.textContent = n.toTimeString().slice(0, 8);
        }
        tick();
        const iv = setInterval(tick, 1000);
        const splash = document.getElementById('splash');
        if (splash) {
            const obs = new MutationObserver(() => {
                if (splash.style.display === 'none') { clearInterval(iv); obs.disconnect(); }
            });
            obs.observe(splash, { attributes: true, attributeFilter: ['style'] });
        }
    })();

    let bootLogs = [
        "Spooling FPS Engine cores...",
        "Mapping SurfaceFlinger frame paths...",
        "Calibrating HWUI render pipeline...",
        "Tuning input latency channels...",
        "Amplifying GPU throughput...",
        "Authenticating: Murilo...",
        "Wards Sealed. Welcome."
    ];

    (function runSplash() {
        const START = performance.now();
        const TOTAL_MS = 3600;
        const easeOut = t => 1 - Math.pow(1 - t, 3);
        let logIndex = -1;
        let lastPct = -1;

        const fill   = document.getElementById('splash-progress');
        const glow   = document.getElementById('sp-progress-glow');
        const pctEl  = document.getElementById('sp-pct');
        const sysLog = document.getElementById('sysLog');
        const splashEl = document.getElementById('splash');

        function swapLog(text) {
            if (!sysLog) return;
            sysLog.classList.add('is-swapping');
            setTimeout(() => {
                sysLog.innerText = text;
                sysLog.classList.remove('is-swapping');
            }, 220);
        }

        function finish() {
            if (!splashEl) return;
            splashEl.classList.add('bloom');
            setTimeout(() => splashEl.classList.add('hiding'), 420);
            setTimeout(() => {
                splashEl.style.display = 'none';
                splashEl.classList.remove('hiding', 'bloom');
                init3DPhysics();
                const strings = getLang();
                showToast(strings.toast_boot, "💎");
                setInterval(updateMetrics, 2000);
                updateMetrics();
            }, 1500);
            applyLanguage(currentLang);
        }

        function frame(now) {
            const t = Math.min(1, (now - START) / TOTAL_MS);
            const eased = easeOut(t);
            const displayed = eased * 100;

            const pct = Math.floor(displayed);
            if (pct !== lastPct) {
                lastPct = pct;
                if (fill)  fill.style.width = displayed + '%';
                if (glow)  glow.style.width = displayed + '%';
                if (pctEl) pctEl.textContent = pct + '%';
            }

            const targetLog = Math.min(bootLogs.length - 1, Math.floor(eased * bootLogs.length));
            if (targetLog !== logIndex) {
                logIndex = targetLog;
                swapLog(bootLogs[logIndex]);
            }

            if (t < 1) requestAnimationFrame(frame);
            else finish();
        }

        requestAnimationFrame(frame);
    })();
};

