function hexToRgb(hex) {
  const h = String(hex || '').replace('#', '');
  const full = h.length === 3 ? h.split('').map(c => c + c).join('') : h;
  const n = parseInt(full, 16);
  if (isNaN(n)) return '224,30,43';
  return `${(n >> 16) & 255},${(n >> 8) & 255},${n & 255}`;
}

function setTheme(name, element) {
  const theme = themes[name];
  if (!theme) return;

  const root = document.documentElement;

  // Core color tokens
  root.style.setProperty('--bg-dark',       theme.bg);
  root.style.setProperty('--bg-deep',       theme.bg);
  root.style.setProperty('--surface-1',     theme.glass);
  root.style.setProperty('--surface-2',     theme.glass);
  root.style.setProperty('--glass-bg',      theme.glass);
  root.style.setProperty('--glass-border',  theme.border);
  root.style.setProperty('--border',        theme.border);
  root.style.setProperty('--border-bright', theme.border.replace(/[\d.]+\)$/, '0.45)'));
  root.style.setProperty('--acc',           theme.acc);
  root.style.setProperty('--acc2',          theme.acc2);
  root.style.setProperty('--acc-rgb',       hexToRgb(theme.acc));
  root.style.setProperty('--acc2-rgb',      hexToRgb(theme.acc2));
  root.style.setProperty('--acc-glow',      theme.glow || 'rgba(0,242,254,0.22)');
  root.style.setProperty('--acc-glow-sm',   (theme.glow || 'rgba(0,242,254,0.12)').replace(/[\d.]+\)$/, '0.10)'));

  // Animate transition
  document.body.style.transition = 'background 350ms cubic-bezier(0.4,0,0.2,1)';

  // Active state on card
  document.querySelectorAll('.theme-card').forEach(c => c.classList.remove('active-theme'));
  if (element && element.classList) element.classList.add('active-theme');

  // Haptic pulse (Android WebView)
  if (window.navigator && window.navigator.vibrate) navigator.vibrate(18);

  localStorage.setItem('mosTheme', name);

  // Flash toast
  if (typeof showToast === 'function') {
    const labels = {
      darkfantasy:'Dark Fantasy', og:'OG Classic',
      cyan:'Cyber Cyan', purple:'Quantum Purple', red:'Inferno Red', green:'Matrix Green',
      gold:'God Tier Gold', midnight:'Midnight Indigo', rose:'Rose Quartz', sakura:'Sakura Bloom',
      aurora:'Aurora Borealis', ocean:'Deep Ocean', amoled:'Pure AMOLED', slate:'Slate Grey',
      nebula:'Nebula Storm', solar:'Solar Flare', arctic:'Arctic Frost', lava:'Lava Core',
      toxic:'Toxic Acid', galaxy:'Galaxy Core', copper:'Copper Strike', void:'Void Black',
      mint:'Mint Fresh', crimson:'Crimson Dusk'
    };
    showToast('🎨 ' + (labels[name] || name) + ' applied');
  }
}

window.addEventListener('load', () => {
  const savedTheme = localStorage.getItem('mosTheme') || 'slate';
  if (savedTheme && themes[savedTheme]) {
    const card = document.querySelector(`.theme-card[onclick*="${savedTheme}"]`);
    setTheme(savedTheme, card || null);
  }
  // Restore saved click sound UI
  const savedSound = localStorage.getItem('mosClickSound') || 'neon';
  currentClickSound = savedSound;
  document.querySelectorAll('.sound-card').forEach(c => c.classList.remove('active-sound'));
  const activeCard = document.querySelector(`.sound-card[data-sound="${savedSound}"]`);
  if (activeCard) activeCard.classList.add('active-sound');
});

/* ── MUSIC PLAYER ── */
(function() {
    const audio = document.getElementById('bgMusic');
    const btn   = document.getElementById('music-btn');
    const fill  = document.getElementById('music-progress-fill');
    const cur   = document.getElementById('music-cur');
    const dur   = document.getElementById('music-dur');
    const vol   = document.getElementById('music-vol');
    let playing = false;
    let autoplayDone = false;

    function fmt(s) {
        if (!isFinite(s)) return '--:--';
        const m = Math.floor(s / 60);
        const sec = Math.floor(s % 60);
        return m + ':' + (sec < 10 ? '0' : '') + sec;
    }

    function startPlay() {
        audio.volume = parseFloat(vol.value);
        audio.play().then(() => {
            btn.textContent = '⏸️';
            playing = true;
        }).catch(() => {});
    }

    // Auto-play on first user interaction (bypasses browser autoplay policy)
    function handleFirstInteraction() {
        if (autoplayDone) return;
        autoplayDone = true;
        document.removeEventListener('touchstart', handleFirstInteraction);
        document.removeEventListener('click', handleFirstInteraction);
        startPlay();
    }
    document.addEventListener('touchstart', handleFirstInteraction, { once: true });
    document.addEventListener('click', handleFirstInteraction, { once: true });

    // Also try immediate autoplay (works if browser allows it)
    audio.addEventListener('canplaythrough', () => {
        if (!autoplayDone) {
            audio.play().then(() => {
                autoplayDone = true;
                btn.textContent = '⏸️';
                playing = true;
            }).catch(() => {
                // Will be picked up by first-interaction handler
            });
        }
    }, { once: true });

    window.toggleMusic = function() {
        autoplayDone = true; // user took manual control
        if (playing) {
            audio.pause();
            btn.textContent = '▶️';
            playing = false;
        } else {
            startPlay();
        }
    };

    // Keep playing state in sync with actual audio state
    audio.addEventListener('play',  () => { playing = true;  btn.textContent = '⏸️'; });
    audio.addEventListener('pause', () => { playing = false; btn.textContent = '▶️'; });

    window.setMusicVol = function(v) {
        audio.volume = parseFloat(v);
    };

    window.seekMusic = function(e) {
        if (!audio.duration) return;
        const rect = e.currentTarget.getBoundingClientRect();
        const pct  = (e.clientX - rect.left) / rect.width;
        audio.currentTime = pct * audio.duration;
    };

    audio.addEventListener('timeupdate', () => {
        if (!audio.duration) return;
        const pct = (audio.currentTime / audio.duration) * 100;
        fill.style.width = pct + '%';
        cur.textContent  = fmt(audio.currentTime);
    });

    audio.addEventListener('loadedmetadata', () => {
        dur.textContent = fmt(audio.duration);
    });

    audio.addEventListener('ended', () => {
        btn.textContent = '▶️';
        playing = false;
    });

    // Remember volume across sessions
    const savedVol = localStorage.getItem('mosMusic_vol');
    if (savedVol !== null) {
        vol.value = savedVol;
        audio.volume = parseFloat(savedVol);
    }
    vol.addEventListener('input', () => {
        localStorage.setItem('mosMusic_vol', vol.value);
    });
})();

