/* ═══════════════════════════════════════════════════════════════════
   FINAL MOBILE FIX — ensure nav and main-content never block touches.
   All pointer-events are controlled ONLY by CSS (.page / .page.active).
   JS must never set inline pointer-events on .page elements.
   ═══════════════════════════════════════════════════════════════════ */
document.addEventListener('DOMContentLoaded', function() {
    setTimeout(restoreSavedPreset, 350);
});

window.addEventListener('DOMContentLoaded', function() {
    // Ensure nav has no inline overrides
    const nav = document.querySelector('.bottom-nav');
    if (nav) {
        nav.style.removeProperty('pointer-events');
        nav.style.removeProperty('z-index');
    }

    // Strip any stale inline overrides from all pages so CSS rules take over
    document.querySelectorAll('.page').forEach(function(p) {
        p.style.removeProperty('pointer-events');
        // Do NOT remove visibility — CSS now uses visibility:hidden on inactive pages
        // to fully block touch/click bleed-through from stacked pages
    });

    // Ensure nav-items are tappable (no inline override needed — CSS handles it)
    document.querySelectorAll('.nav-item').forEach(function(item) {
        item.style.removeProperty('pointer-events');
    });

    // Ensure the first active page is correct
    const firstPage = document.querySelector('.page.active');
    if (!firstPage) {
        const vip = document.getElementById('tab-vip');
        if (vip) vip.classList.add('active');
    }
});

